import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ioBroker: automatic role mapping","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/mqtt-client/iobroker-roles.md","filePath":"en/projects/mqtt-client/iobroker-roles.md","lastUpdated":1794045175000}'),r={name:"en/projects/mqtt-client/iobroker-roles.md"};function c(s,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="iobroker-role-mapping" tabindex="-1">ioBroker: automatic role mapping <a class="header-anchor" href="#iobroker-role-mapping" aria-label="Permalink to &quot;ioBroker: automatic role mapping {#iobroker-role-mapping}&quot;">​</a></h1><p>The optional JavaScript ships with MQTT-Client <strong>0.1.24</strong> and runs in the ioBroker JavaScript adapter. It uses transmitted <code>device_class</code> and <code>unit_of_measurement</code> metadata. Only unambiguous cases are mapped; MQTT values, types, units, credentials and return channels are not rewritten.</p><h2 id="vis2" tabindex="-1">New in 0.1.24: one VIS-2 state for feedback and commands <a class="header-anchor" href="#vis2" aria-label="Permalink to &quot;New in 0.1.24: one VIS-2 state for feedback and commands {#vis2}&quot;">​</a></h2><p>The script now creates virtual states and folders automatically below <code>0_userdata.0.ugso_mqtt</code>. It targets the APIs of ioBroker JavaScript adapter <strong>10.4.10</strong>. First <strong>update MQTT-Client to 0.1.24</strong> and reconnect: its new selection catalog binds each entity to its current topic and command permission. Old retained topics must not create duplicate controls.</p><p>Initially keep these settings at the top of the complete script:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outputMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virtual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mqttRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mqtt.0.ha_external&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualBackupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt_helper.backup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>After checking preview, change to <code>mode: &#39;apply&#39;</code> and restart. <strong>The backup state, folders and new VIS-2 states are created automatically.</strong> Preview deliberately creates nothing. Existing unrelated states, aliases and manual roles are not overwritten. Your existing alias, for example below <code>alias.0.HA</code>, need not be removed.</p><p>Example: <code>mqtt.0.ha_external.claudia_pc.switch.state</code> and its <code>mqtt.0.ha_external.claudia_pc.switch.set</code> return channel become <code>0_userdata.0.ugso_mqtt.claudia_pc.switch.state</code>. <strong>Use only this virtual state in VIS 2.</strong></p><table tabindex="0"><thead><tr><th>Direction/function</th><th>Behaviour</th></tr></thead><tbody><tr><td>MQTT feedback → VIS 2</td><td>Confirmed state with <code>ack: true</code></td></tr><tr><td>VIS-2 operation → MQTT command</td><td>Only current requests with <code>ack: false</code> go to <code>/set</code></td></tr><tr><td>Switch</td><td>Virtually normalize <code>on</code>/<code>off</code> to booleans; send <code>ON</code>/<code>OFF</code> back</td></tr><tr><td>Brightness</td><td>Percentage 0–100 with checked limits</td></tr><tr><td>RGB</td><td>MQTT JSON array ↔ virtual hexadecimal <code>#RRGGBB</code></td></tr><tr><td>Effect</td><td>Only options in the current effect list</td></tr><tr><td>Color temperature</td><td>Integer Kelvin within current limits</td></tr><tr><td>Numbers, selects and text</td><td>Validate available limits or options</td></tr><tr><td>Dates, measurements and battery</td><td>Read-only; original MQTT values remain unchanged</td></tr></tbody></table><p>Creation, startup and restart send no control commands and never replay old requests. A new HA state update confirms the value; broker acceptance alone does not confirm execution. Without a fresh response for approximately 30 seconds, the request remains unacknowledged with error quality <code>q: 128</code>. When deselected, unknown or offline, the last value is preserved with <code>q: 130</code> and commands are blocked. No artificial zero/off values are used.</p><p>The <code>virtualBackupId</code> journal is saved and verified before each new state is created. It holds mappings and object definitions, not MQTT credentials or current measurements. Virtual mode leaves original MQTT objects unchanged. With <code>mode: &#39;restore&#39;</code>, virtual values and dashboard references are preserved; own virtual command states become read-only and synchronization ends. Stop the script afterwards.</p><p>The previous functionality remains available through <code>outputMode: &#39;roles&#39;</code>. The direct-role/alias rules and restore instructions below apply to that role mode; the mapping tables also describe virtual states semantically. <strong>Run only one helper copy at a time.</strong> Missing optional attributes and a journal not yet created no longer generate the previous <code>getState</code> warnings.</p><h2 id="installation" tabindex="-1">Installation and backup <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation and backup {#installation}&quot;">​</a></h2><ol><li>First export the affected MQTT objects with their states and existing scripts in ioBroker Admin, or create a complete backup.</li><li>In MQTT-Client choose <strong>ioBroker-/VIS-2-Helfer herunterladen</strong>, or <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/mqtt_client/app/iobroker/ugso-mqtt-role-mapper.js" target="_blank" rel="noreferrer">download the script</a>.</li><li>Under <strong>Scripts</strong> in ioBroker, create a <strong>JavaScript</strong> and paste the complete file. Run only one copy in one JavaScript instance.</li><li>Set <code>mqttRoot</code> to your MQTT path, for example <code>mqtt.0.ha_external</code>. Wildcards are not allowed.</li><li>Keep <code>mode: &#39;preview&#39;</code>, start the script and inspect its log. Preview performs no writes.</li><li>Add manually assigned generic <code>state</code> roles to <code>excludeIds</code>. Such manual roles cannot be distinguished from automatically assigned defaults.</li><li>After checking, set <code>mode: &#39;apply&#39;</code> and restart the script. Allow <code>setObject</code> in the JavaScript instance settings. The instance must be able to read MQTT states.</li></ol><p>Before each change, the original role is saved in the JSON state <code>0_userdata.0.ugso_mqtt_roles.backup</code> and persistence is verified. This journal contains no meter values or credentials. A backup failure prevents the subsequent role change. Export this backup state too and keep it.</p><p>Specific roles such as <code>date</code>, <code>text</code> or <code>value.temperature</code> are not replaced. A later manual role change prevents automatic reapplication to that state. Existing aliases are never overwritten.</p><h2 id="aliases" tabindex="-1">Direct roles and read-only aliases <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Direct roles and read-only aliases {#aliases}&quot;">​</a></h2><p>Dates and timestamps receive <code>date</code> directly. Stored text and write permissions are preserved; HA <code>uptime</code> represents a startup timestamp, not elapsed duration.</p><p>Measurement and binary sensor roles in ioBroker are read-only. If the MQTT source is already read-only, only its generic role is replaced. If it is writable, a read-only alias is created below <code>alias.0.ugso_mqtt_roles</code> instead; the original MQTT role and permissions remain unchanged. Use the alias for visualization and analysis. Its values continue to come from the original MQTT state.</p><p>The script checks metadata and actual value types. It does not guess types from device names or <code>on</code>/<code>off</code> strings. Missing metadata, incompatible units, invalid dates and unknown classes are skipped. There are no conversions or control commands. Transmit <code>device_class</code> and, for measurements, the unit; include these available attributes when selecting manually. Label forwarding includes available standard metadata automatically.</p><table tabindex="0"><thead><tr><th>HA device class</th><th>ioBroker role</th><th>Validation</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>date</code></td><td>Valid <code>YYYY-MM-DD</code></td></tr><tr><td><code>timestamp</code>, <code>uptime</code></td><td><code>date</code></td><td>ISO timestamp including timezone</td></tr></tbody></table><h2 id="numeric" tabindex="-1">Implemented numeric mappings <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Implemented numeric mappings {#numeric}&quot;">​</a></h2><p>The table lists the units actually accepted. Other units are preserved and skipped; mA or mV, for example, are not silently converted.</p><table tabindex="0"><thead><tr><th>HA device class</th><th>ioBroker role</th><th>Accepted units</th></tr></thead><tbody><tr><td><code>temperature</code></td><td><code>value.temperature</code></td><td><code>°C</code>, <code>°F</code>, <code>K</code></td></tr><tr><td><code>humidity</code></td><td><code>value.humidity</code></td><td><code>%</code></td></tr><tr><td><code>absolute_humidity</code></td><td><code>value.humidity.absolute</code></td><td><code>g/m³</code>, <code>mg/m³</code></td></tr><tr><td><code>battery</code></td><td><code>value.battery</code></td><td><code>%</code></td></tr><tr><td><code>voltage</code></td><td><code>value.voltage</code></td><td><code>V</code></td></tr><tr><td><code>current</code></td><td><code>value.current</code></td><td><code>A</code></td></tr><tr><td><code>power</code></td><td><code>value.power</code></td><td><code>W</code>, <code>kW</code></td></tr><tr><td><code>energy</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>energy_storage</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>reactive_power</code></td><td><code>value.power.reactive</code></td><td><code>var</code>, <code>kvar</code>, <code>kVar</code></td></tr><tr><td><code>reactive_energy</code></td><td><code>value.energy.reactive</code></td><td><code>varh</code>, <code>kvarh</code>, <code>kVarh</code></td></tr><tr><td><code>frequency</code></td><td><code>value.frequency</code></td><td><code>Hz</code></td></tr><tr><td><code>pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>atmospheric_pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>illuminance</code></td><td><code>value.brightness</code></td><td><code>lx</code>, <code>lux</code></td></tr><tr><td><code>distance</code></td><td><code>value.distance</code></td><td><code>m</code>, <code>km</code>, <code>cm</code>, <code>mm</code>, <code>mi</code>, <code>nmi</code>, <code>yd</code>, <code>ft</code>, <code>in</code></td></tr><tr><td><code>duration</code></td><td><code>value.interval</code></td><td><code>s</code>, <code>ms</code>, <code>h</code>, <code>d</code></td></tr><tr><td><code>wind_speed</code></td><td><code>value.speed</code></td><td><code>m/s</code>, <code>km/h</code>, <code>mph</code>, <code>kn</code></td></tr><tr><td><code>volume_flow_rate</code></td><td><code>value.flow</code></td><td><code>m³/h</code></td></tr><tr><td><code>signal_strength</code></td><td><code>value.rssi</code></td><td><code>dBm</code></td></tr><tr><td><code>aqi</code></td><td><code>value.airquality</code></td><td>—</td></tr><tr><td><code>carbon_dioxide</code></td><td><code>value.co2</code></td><td><code>ppm</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>value.co</code></td><td><code>ppm</code></td></tr><tr><td><code>nitrogen_monoxide</code></td><td><code>value.no</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>nitrogen_dioxide</code></td><td><code>value.no2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>ozone</code></td><td><code>value.o3</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>sulphur_dioxide</code></td><td><code>value.so2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm1</code></td><td><code>value.pm1</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm25</code></td><td><code>value.pm25</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm10</code></td><td><code>value.pm10</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>radon</code></td><td><code>value.rn</code></td><td><code>Bq/m³</code></td></tr><tr><td><code>volatile_organic_compounds</code></td><td><code>value.tvoc</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>volatile_organic_compounds_parts</code></td><td><code>value.tvoc</code></td><td><code>ppb</code></td></tr></tbody></table><h2 id="binary" tabindex="-1">Binary sensors <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Binary sensors {#binary}&quot;">​</a></h2><p>Only actual boolean values with a matching object type are accepted. Standard HA <code>on</code> and <code>off</code> strings remain untouched and are not given boolean roles. For <code>battery</code>, true means low battery; for <code>lock</code>, true means unlocked.</p><table tabindex="0"><thead><tr><th>HA device class</th><th>ioBroker role</th></tr></thead><tbody><tr><td><code>battery</code></td><td><code>indicator.lowbat</code></td></tr><tr><td><code>connectivity</code></td><td><code>indicator.reachable</code></td></tr><tr><td><code>door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>garage_door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>window</code></td><td><code>sensor.window</code></td></tr><tr><td><code>opening</code></td><td><code>sensor.contact</code></td></tr><tr><td><code>lock</code></td><td><code>sensor.lock</code></td></tr><tr><td><code>motion</code></td><td><code>sensor.motion</code></td></tr><tr><td><code>moisture</code></td><td><code>sensor.alarm.flood</code></td></tr><tr><td><code>smoke</code></td><td><code>sensor.alarm.fire</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>sensor.alarm.co</code></td></tr><tr><td><code>light</code></td><td><code>sensor.light</code></td></tr><tr><td><code>sound</code></td><td><code>sensor.noise</code></td></tr><tr><td><code>problem</code></td><td><code>indicator.error</code></td></tr><tr><td><code>running</code></td><td><code>indicator.working</code></td></tr></tbody></table><h2 id="conditional" tabindex="-1">Further mappings considered <a class="header-anchor" href="#conditional" aria-label="Permalink to &quot;Further mappings considered {#conditional}&quot;">​</a></h2><p>Role-only mode does not apply these cases automatically. Virtual mode now implements the Light and switch functions below with the described checks; fill levels, consumption/production and ambiguous measurement classes are still not guessed.</p><table tabindex="0"><thead><tr><th>HA class/function</th><th>Possible role</th><th>Additional requirement</th></tr></thead><tbody><tr><td><code>volume_storage</code></td><td><code>value.fill</code></td><td>Confirm an actual container fill level</td></tr><tr><td><code>water</code>, <code>gas</code></td><td>Generic measurement</td><td>Consumption is not a fill level</td></tr><tr><td><code>energy</code></td><td><code>value.energy.consumed</code> / <code>value.energy.produced</code></td><td>Explicit consumption/production information</td></tr><tr><td><code>speed</code></td><td><code>value.speed</code></td><td>Do not assume every speed is wind</td></tr><tr><td>Numeric <code>moisture</code></td><td>Generic measurement</td><td>Distinguish from a binary water alarm</td></tr><tr><td>Brightness feedback</td><td><code>value.dimmer</code></td><td>Confirm percentage and Light function</td></tr><tr><td>Brightness command</td><td><code>level.dimmer</code></td><td>Correctly connect a separate return channel</td></tr><tr><td>Switch feedback</td><td><code>sensor.switch</code></td><td>Normalize a boolean value</td></tr><tr><td>Switch command</td><td><code>switch</code> / <code>switch.light</code></td><td>Connect <code>/set</code>; send no setup command</td></tr><tr><td>Color-temperature command</td><td><code>level.color.temperature</code></td><td>Kelvin, limits and return channel</td></tr><tr><td>Effect selection</td><td><code>level.effect</code></td><td>Effect list and return channel</td></tr><tr><td>RGB control</td><td><code>level.color.rgb</code></td><td>Convert JSON array to hexadecimal color</td></tr></tbody></table><p>No specific role is guessed for <code>occupancy</code>, <code>presence</code>, <code>moving</code>, <code>plug</code>, binary <code>power</code>, <code>battery_charging</code>, <code>cold</code>, <code>heat</code>, binary <code>gas</code>, <code>glass_break</code>, <code>safety</code>, <code>tamper</code>, <code>update</code> or <code>vibration</code>. Generic <code>sensor</code>/<code>indicator</code> roles or custom rules are possible but excluded from this conservative automatic mapping. All other unlisted classes remain unchanged too.</p><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore {#restore}&quot;">​</a></h2><p>Stop the script, set <code>mode: &#39;restore&#39;</code> and start it again. Only the script&#39;s own role changes are restored, provided the current role and type still match its backup entry. Later manual role changes are preserved. Own unmodified aliases are removed; edited or unrelated aliases remain. Original MQTT values are never deleted.</p><p>Stop the script afterwards. Keep the journal and exclusions. Already recorded states are not processed again with the same journal; a new run requires a deliberately new <code>backupId</code> and, for aliases, an unused <code>aliasRoot</code>.</p><p>Verified locally with simulated ioBroker APIs for preview, backup failures, types, units, manual edits, aliases and restore. Not yet installation-tested on a real ioBroker system.</p><p><a href="https://www.home-assistant.io/integrations/sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Sensor</a> · <a href="https://www.home-assistant.io/integrations/binary_sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Binary sensor</a> · <a href="https://www.iobroker.com/docs/dev/stateroles.md" target="_blank" rel="noreferrer">ioBroker: State roles</a> · <a href="https://github.com/ioBroker/ioBroker.javascript/blob/v10.4.10/docs/en/javascript.md" target="_blank" rel="noreferrer">ioBroker: JavaScript API</a></p>`,36)])])}const m=t(r,[["render",c]]);export{h as __pageData,m as default};
